if (is_post()) {
 try {
  $v=[];$req=['cif_number','full_name','father_name','mother_name','date_of_birth','gender','nationality','profession','source_of_fund','phone','id_type','id_number','branch_id','status','kyc_status'];
  foreach($req as $x) if(posted($x)==='') $errors[]=ucwords(str_replace('_',' ',$x)).' is required.';
  if(posted('email')!==''&&!filter_var(posted('email'),FILTER_VALIDATE_EMAIL))$errors[]='Email is invalid.';
  if(!in_array(posted('gender'),enum_values('gender'),true))$errors[]='Invalid gender.';
  if(!in_array(posted('id_type'),enum_values('id_type'),true))$errors[]='Invalid ID type.';
  if(!in_array(posted('status'),enum_values('customer_status'),true))$errors[]='Invalid customer status.';
  if(!in_array(posted('kyc_status'),enum_values('kyc_status'),true))$errors[]='Invalid KYC status.';
  if(posted('monthly_income')!==''&&!is_numeric(posted('monthly_income'))) $errors[]='Monthly income must be numeric.';
  if(posted('kyc_status')!=='pending' && (posted('kyc_verified_by_employee_id')=='' || posted('kyc_verified_at')==='')) $errors[]='Verified KYC requires verifier and verification time.';
  if(!$errors){
   $sql='INSERT INTO customers(cif_number,full_name,full_name_bn,father_name,mother_name,spouse_name,date_of_birth,gender,nationality,profession,monthly_income,source_of_fund,tin_number,phone,email,id_type,id_number,branch_id,status,kyc_status,kyc_verified_by_employee_id,kyc_verified_at) VALUES(:cif,:name,:bn,:father,:mother,:spouse,:dob,:gender,:nat,:prof,:income,:source,:tin,:phone,:email,:idtype,:idnum,:branch,:status,:kyc,:ver,:verat)';
   db_insert($sql,[':cif'=>posted('cif_number'),':name'=>posted('full_name'),':bn'=>posted_or_null('full_name_bn'),':father'=>posted('father_name'),':mother'=>posted('mother_name'),':spouse'=>posted_or_null('spouse_name'),':dob'=>posted('date_of_birth'),':gender'=>posted('gender'),':nat'=>posted('nationality'),':prof'=>posted('profession'),':income'=>posted_or_null('monthly_income'),':source'=>posted('source_of_fund'),':tin'=>posted_or_null('tin_number'),':phone'=>posted('phone'),':email'=>posted_or_null('email'),':idtype'=>posted('id_type'),':idnum'=>posted('id_number'),':branch'=>(int)posted('branch_id'),':status'=>posted('status'),':kyc'=>posted('kyc_status'),':ver'=>posted_or_null('kyc_verified_by_employee_id'),':verat'=>posted_or_null('kyc_verified_at')]);
   flash_set('success','Customer added successfully.');redirect('customer.php');
  }
 }catch(Throwable $e){$errors[]=exception_message($e);}
}
